import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Pair","description":"","frontmatter":{},"headers":[],"relativePath":"components/pair.md","filePath":"components/pair.md"}'),r={name:"components/pair.md"};function i(n,e,c,l,s,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="pair" tabindex="-1">Pair <a class="header-anchor" href="#pair" aria-label="Permalink to &quot;Pair&quot;">​</a></h1><p>Pair sets a name and a value side by side: a control, or text to read.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the settings of a selection in a panel, where the names form one column at the left. The default is a value that is edited; <code>read</code> is a value to read (a summary, the attributes of a thing) and <code>top</code> a value of several lines, such as a Textarea. Stack pairs in a <a href="./stack">Stack</a> with gap sm, and do not mix edit and read pairs in one column; a column of read pairs is a <a href="./kv">Kv</a>. A form with names above the inputs uses <a href="./field">Field</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>required</td><td>The name</td></tr><tr><td><code>for</code></td><td></td><td>The id of the control the name labels</td></tr><tr><td><code>href</code></td><td></td><td>Makes the name a link</td></tr><tr><td><code>read</code></td><td><code>false</code></td><td>A value to read, not a control</td></tr><tr><td><code>top</code></td><td><code>false</code></td><td>A value of several lines, aligned at the top</td></tr><tr><td><code>note</code></td><td></td><td>A caption under the value</td></tr><tr><td><code>tight</code></td><td><code>false</code></td><td>The name column takes the width of the name</td></tr><tr><td><code>indent</code></td><td><code>0</code></td><td>The depth of a read name in a tree of values</td></tr><tr><td><code>muted</code></td><td><code>false</code></td><td>A weaker read value (empty or inherited)</td></tr><tr><td><code>mono</code></td><td><code>false</code></td><td>The value in the monospace font</td></tr><tr><td><code>clamp</code></td><td><code>false</code></td><td>The value on one line with an ellipsis</td></tr><tr><td><code>children</code></td><td>required</td><td>The control or the value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The name column is 7.5rem wide, gap-sm from the value, and the name is muted, trimmed to its ink and level with the first line of the value. An edit pair has the height of a button (<code>--kata-box</code>) and its control fills the column. A read pair, a pair with a note and a <code>top</code> pair take the height of their content; the note, a caption in the color of the text, is gap-xs under the value. <code>indent</code> moves the name by md for each level. The pair owns the padding at its sides: the inset its container declares, none inside a container with padding. Below 24rem the name sits above the value.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pair/" title="Pair" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pair/" target="_blank" rel="noopener">Pair</a></figcaption></figure>',10)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
